using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "FireBreathEffect", menuName = "Data/Battle/Effects/Sothis/FireBreath Effect")]
public class FireBreathEffect : OnSoulHeatHitValueEffects
{
	public bool IsSoulHeatOnMinimunToActivate()
	{
		return soulHeat.SoulHeatCounter >= soulHeatToTrigger;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		PlayerEffects component = effectOwner.GetComponent<PlayerEffects>();
		ToggleVisualEffect(component);
	}

	public override void OnSoulHeatHitValue(PlayerEffects playerEffects)
	{
		ToggleVisualEffect(playerEffects);
	}

	private void ToggleVisualEffect(PlayerEffects playerEffects)
	{
		if (IsSoulHeatOnMinimunToActivate())
		{
			if (playerEffects.IsEffectActive(this))
			{
				playerEffects.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
			}
		}
		else if (playerEffects.IsEffectActive(this, activateFeedback: false))
		{
			playerEffects.IsEffectActiveGetEffectInstance(this).StopBlinkingFeedback();
		}
	}
}
